INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Serviceanfragen > Störungen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Störungen immer sofort behoben werden, um eine Serviceanfrage abzuschließen?', 2, '[{"text": "Nein", "correct": true, "because": "Priorisierung und Planung können nötig sein"}, {"text": "Ja", "correct": false, "because": "Sofortigkeit hängt von Dringlichkeit ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Störungen in einem IT-System ohne Benachrichtigung der Nutzer bearbeitet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Interne Behebung ist möglich"}, {"text": "Nein", "correct": false, "because": "Benachrichtigung ist oft sinnvoll, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jede Störung, die als Serviceanfrage gemeldet wird, auch ein kritischer Systemfehler?', 2, '[{"text": "Nein", "correct": true, "because": "Störungen variieren in ihrer Schwere"}, {"text": "Ja", "correct": false, "because": "Nicht alle Störungen sind kritisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Störungen durch fehlende Dokumentation schwerer zu beheben sein?', 2, '[{"text": "Ja", "correct": true, "because": "Dokumentation erleichtert Ursachenfindung"}, {"text": "No", "correct": false, "because": "Fehlende Infos erschweren oft die Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Störungen immer auf Hardwarefehler zurückzuführen?', 2, '[{"text": "Nein", "correct": true, "because": "Software oder Konfiguration können Ursachen sein"}, {"text": "Ja", "correct": false, "because": "Störungen haben vielfältige Ursachen"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Bearbeitung einer Störung als Serviceanfrage typischerweise der erste?', 3, '[{"text": "Erfassung der Störung", "correct": true, "because": "Startpunkt für Analyse"}, {"text": "Neustart des Systems", "correct": false, "because": "Erst nach Analyse"}, {"text": "Erstellung eines Berichts", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft oft bei der Identifikation von Störungen?', 2, '[{"text": "Monitoring-System", "correct": true, "because": "Erfasst Anomalien in Echtzeit"}, {"text": "Texteditor", "correct": false, "because": "Nicht für Diagnose geeignet"}, {"text": "Grafiksoftware", "correct": false, "because": "Irrelevant für Störungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel bei der Bearbeitung von Störungen als Serviceanfrage?', 2, '[{"text": "Wiederherstellung des Normalbetriebs", "correct": true, "because": "Fokus auf Funktionalität"}, {"text": "Erhöhung der Systemkomplexität", "correct": false, "because": "Nicht gewünscht"}, {"text": "Verlängerung der Ausfallzeit", "correct": false, "because": "Gegenteil ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann bei der Bearbeitung von Störungen durch unzureichende Analyse entstehen?', 3, '[{"text": "Wiederholte Störungen", "correct": true, "because": "Ursache nicht behoben"}, {"text": "Schnellere Lösung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Eskalation", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird oft genutzt, um die Priorität einer Störung zu bestimmen?', 2, '[{"text": "Auswirkung auf den Betrieb", "correct": true, "because": "Definiert Dringlichkeit"}, {"text": "Anzahl der Benutzer", "correct": false, "because": "Nur ein Faktor"}, {"text": "Zeitpunkt der Meldung", "correct": false, "because": "Weniger entscheidend"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Bearbeitung von Störungen als Serviceanfrage typisch?', 4, '[{"text": "Störungsmeldung", "correct": true, "because": "Erfassung ist erster Schritt"}, {"text": "Ursachenanalyse", "correct": true, "because": "Findet Problemursache"}, {"text": "Behebung", "correct": true, "because": "Löst die Störung"}, {"text": "Farbauswahl der Meldung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursachen können Störungen in einem IT-System haben?', 3, '[{"text": "Hardwareausfall", "correct": true, "because": "Physische Defekte"}, {"text": "Softwarefehler", "correct": true, "because": "Programmierprobleme"}, {"text": "Benutzerfehler", "correct": true, "because": "Falsche Bedienung"}, {"text": "Bürogestaltung", "correct": false, "because": "Nicht technisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Bearbeitung von Störungen verzögern?', 4, '[{"text": "Unklare Meldungen", "correct": true, "because": "Erschwert Analyse"}, {"text": "Fehlende Ressourcen", "correct": true, "because": "Bremst Behebung"}, {"text": "Mangelnde Dokumentation", "correct": true, "because": "Verlangsamt Verständnis"}, {"text": "Zu schnelle Reaktion", "correct": false, "because": "Kein Hindernis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen können Störungen als Serviceanfrage minimieren?', 3, '[{"text": "Regelmäßige Wartung", "correct": true, "because": "Verhindert Probleme"}, {"text": "Proaktives Monitoring", "correct": true, "because": "Früherkennung"}, {"text": "Schulung der Benutzer", "correct": true, "because": "Reduziert Fehlbedienung"}, {"text": "Änderung der Beleuchtung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine schnelle Bearbeitung von Störungen?', 3, '[{"text": "Geringere Ausfallzeiten", "correct": true, "because": "Schnelle Wiederherstellung"}, {"text": "Höhere Kundenzufriedenheit", "correct": true, "because": "Zuverlässiger Service"}, {"text": "Bessere Systemstabilität", "correct": true, "because": "Vermeidet Folgefehler"}, {"text": "Höhere Hardwarekosten", "correct": false, "because": "Nicht relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Störungen können durch proaktives Monitoring frühzeitig erkannt werden. b) Jede Störung erfordert einen Systemneustart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Monitoring ja, Neustart nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine detaillierte Störungsmeldung erleichtert die Behebung. b) Störungen sind immer sofort sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Details ja, Sichtbarkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Bearbeitung von Störungen kann eskaliert werden, wenn nötig. b) Störungen betreffen nur die Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eskalation ja, Ursachen vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Störungen können durch Benutzerfehler verursacht werden. b) Die Behebung von Störungen ist immer automatisiert möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Benutzerfehler ja, Automatisierung begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine schnelle Reaktion auf Störungen reduziert Auswirkungen. b) Störungen sind immer vorhersehbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reaktion ja, Vorhersage schwierig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

